command:
cd .. && RT=$(mktemp -d) && cat > $RT/fake-run.sh <<'EOF'
#!/bin/bash
seat="$2"
case "$FAKE_MODE" in
  blocker_no_code) echo "{\"outcome\":\"named_blocker\",\"lanes\":[{\"lane\":\"handler-$seat\",\"failure_code\":null}]}";;
  answered_bad_exit) echo "{\"outcome\":\"answered\",\"lanes\":[{\"lane\":\"handler-$seat\",\"has_token\":true}]}"; exit 1;;
  answered_no_token) echo "{\"outcome\":\"answered\",\"lanes\":[{\"lane\":\"handler-$seat\",\"has_token\":false}]}";;
  wrong_seat) echo "{\"outcome\":\"answered\",\"lanes\":[{\"lane\":\"handler-somebody-else\",\"has_token\":true}]}";;
  garbage) echo 'not json';;
  all_blocked) echo "{\"outcome\":\"named_blocker\",\"lanes\":[{\"lane\":\"handler-$seat\",\"failure_code\":\"provider_down\"}]}";;
esac
EOF
chmod +x $RT/fake-run.sh && fails=0 && for m in blocker_no_code answered_bad_exit answered_no_token wrong_seat garbage; do FAKE_MODE=$m uv run --project . python scripts/seat_ping_ladder.py --seat s1 --out-dir $RT/$m --run-sh $RT/fake-run.sh >/dev/null 2>&1; [ $? -eq 1 ] || { echo RED_PATH_WENT_GREEN_$m; fails=1; }; done; FAKE_MODE=all_blocked uv run --project . python scripts/seat_ping_ladder.py --seat s1 --out-dir $RT/ab --run-sh $RT/fake-run.sh >/dev/null 2>&1; [ $? -eq 3 ] || { echo ALL_BLOCKED_NOT_EXIT_3; fails=1; }; [ $fails -eq 0 ] && echo ALL_RED_PATHS_STAY_RED
